  public function getTiposRetencion($prov_periodo_validez_id){
  	
	$c=new Criteria();
    $c->add(ProvTipoRetencionAprobadaPeer::PROV_PERIODO_VALIDEZ_ID,$prov_periodo_validez_id);
    $prov_tipo_retencionaprobadas = ProvTipoRetencionAprobadaPeer::doSelect($c);
    
    $tipos="";
    foreach($prov_tipo_retencionaprobadas as $prov_tipo_retencionaprobada){
		$tipos.=$prov_tipo_retencionaprobada->getProvTipoRetencion()." | ";
	}
	return $tipos;
    
  }
 
