  public function executeUpdate()
  {
    if (!$this->getRequestParameter('proveedor_id'))
    {
      $proveedor = new Proveedor();
      $edit=false; 
    }
    else
    { 
      $edit=true;  
      $proveedor = ProveedorPeer::retrieveByPk($this->getRequestParameter('proveedor_id'));
      $this->forward404Unless($proveedor);
    }
    //$proveedor->setProveedorId($this->getRequestParameter('proveedor_id'));
    $proveedor->setNombre($this->getRequestParameter('nombre'));
    $proveedor->setNit($this->getRequestParameter('nit'));
    $proveedor->setRepresentanteLegal($this->getRequestParameter('representante_legal'));
    $proveedor->setIdentificacionRl($this->getRequestParameter('identificacion_rl'));
    $proveedor->setDireccion($this->getRequestParameter('direccion'));
    $proveedor->setTelefono($this->getRequestParameter('telefono'));
    $proveedor->setNaturalezaJuridica($this->getRequestParameter('naturaleza_juridica'));
    $proveedor->setNombreComercial($this->getRequestParameter('nombre_comercial'));
    $proveedor->setFechaIngreso($this->getRequestParameter('fecha_ingreso') ? $this->getRequestParameter('fecha_ingreso') : null);
    //$proveedor->setFechaIngreso($this->getRequestParameter('fecha_ingreso'));
    $proveedor->setPaisId($this->getRequestParameter('pais_id'));
    //$proveedor->setProvEstadoId($this->getRequestParameter('prov_estado_id'));
    $proveedor->setProvEstadoId(1);//1 es estado Para creacion
    $proveedor->setFechaCreacion(date("Y-m-d"));
    $proveedor->save();
    $this->createPeriodoValidez($proveedor->getPrimaryKey());
    if($edit==true){
       return $this->redirect($this->getRequest()->getScriptName().'/proveedor/show?proveedor_id='.$proveedor->getProveedorId());
    }    
    else{
     //region enviar email
     $msge="Este mensaje es para informarle que se radico un proveedor en SIMAD WEB 4.0: 
     Proveedor:".$proveedor->getNombre();
     $this->enviarAlertas(10,$msge);
        
     return $this->redirect($this->getRequest()->getScriptName().'/proveedor/list');   
    }
  }
  
